// D758 (#1864) — the rules of the Templates tab's "Generated by the platform"
// group. The documents and their library rows are the Worker's
// (`GET /api/admin/contracts/templates/generated`); this file only says how a
// row's state reads and when the group shows. Pure: no request, no React.

/** The info pill every generated card carries (board L8's legend). */
export const GENERATED_PILL = 'Generated by the platform';

/**
 * A library row's state on a generated card (D758 decision 6). It is the
 * active row's, never a publication's, so it never reads "Published v[N]".
 */
export function proseState(row) {
  if (!row || row.missing) return { label: 'Not in the catalog', tone: 'info' };
  if (row.has_body) return { label: 'Has a body', tone: 'ok' };
  if (row.counsel_draft) return { label: 'Stub — counsel to draft.', tone: 'warn' };
  return { label: 'No body in the store yet.', tone: 'neutral' };
}

/**
 * The generated documents the group draws (decision 11). They are not layer
 * rows and have no state, so the group shows only under "Layer · All" and the
 * state "All". Search narrows it by title, as the catalog's own search does.
 */
export function visibleGenerated(items, { q = '', layer = 'all', state = 'all' } = {}) {
  if (layer !== 'all' || state !== 'all') return [];
  const list = Array.isArray(items) ? items : [];
  const needle = String(q || '').trim().toLowerCase();
  return needle ? list.filter((item) => String(item?.title || '').toLowerCase().includes(needle)) : list;
}
